  function missionPage(){return sectionHead('FIELD ATLAS / SOUTH ASIA','A living view of the high Himalaya','Start from a real place. Load observations and build an evidence-backed investigation.','<button class="btn" data-action="demo">Open case study ↗</button><button class="btn primary" data-action="new-investigation">＋ New investigation</button>')+
  '<section class="hero-grid"><div class="map-panel"><div class="panel-top"><div><span class="eyebrow">GEOGRAPHIC OPERATING AREA</span><h2>South Lhonak · North Sikkim</h2></div><span class="map-chip"><i class="live-dot"></i> REAL MAP</span></div><div id="main-map" class="map large-map"></div><div class="map-foot"><span>27.9500° N / 88.2300° E</span><span>WGS84 · EPSG:4326</span><button class="text-btn" data-nav="lakes">Open site record ↗</button></div></div><div class="side-stack"><div class="paper-card site-card"><div class="eyebrow">SELECTED STUDY SITE</div><h2>South Lhonak Lake</h2><p>Glacial lake · North Sikkim, India</p><div class="site-coords mono">27°57′N<br>88°14′E</div><div class="line"></div><div class="kv"><span>Elevation reference</span><b>~5,200 m</b></div><div class="kv"><span>Study mode</span><b>Historical reconstruction</b></div><div class="kv"><span>Study boundary</span><b id="aoi-readout">Default search extent</b></div><button class="btn dark full" data-nav="observations">Investigate this lake ↗</button></div><div class="paper-card"><div class="eyebrow">YOUR WORKSPACE</div><div class="big-number">'+state.investigations.length+'</div><b>Saved investigations</b><p class="muted">Stored in this browser profile.</p><button class="text-btn" data-nav="investigations">View investigations →</button></div></div></section>'+
  '<section class="section-block"><div class="section-title"><div><div class="eyebrow">WORKING SURFACE</div><h2>Choose your next operation</h2></div></div><div class="operation-grid"><button class="operation" data-nav="observations"><span>01 / OBSERVE</span><b>Satellite observation</b><small>Search real Sentinel acquisitions and inspect source metadata.</small><em>Open Observation Lab ↗</em></button><button class="operation" data-nav="environment"><span>02 / CONTEXT</span><b>Weather history</b><small>Retrieve historical precipitation, temperature and wind reanalysis.</small><em>Open environmental desk ↗</em></button><button class="operation" data-nav="breach"><span>03 / ENGINEER</span><b>Breach scenarios</b><small>Build documented HEC-RAS input configurations and export them.</small><em>Open Breach Laboratory ↗</em></button><button class="operation" data-nav="impact"><span>04 / ASSESS</span><b>Impact atlas</b><small>Inspect actual map features and prepare a study-area exposure workflow.</small><em>Open Impact Atlas ↗</em></button></div></section>'+
  '<section class="section-block"><div class="section-title"><div><div class="eyebrow">LOCAL RECORDS</div><h2>Recent investigations</h2></div><button class="text-btn" data-nav="investigations">View all →</button></div>'+investigationList()+'</section>'; }
  function investigationList(){if(!state.investigations.length)return '<div class="empty-state"><span>⌁</span><b>No investigations created yet</b><p>Create a study to save its area, selected dates, sources and scenario configurations.</p><button class="btn primary" data-action="new-investigation">Create first investigation</button></div>';return '<div class="record-list">'+state.investigations.map(i=>'<button class="record-row" data-open-investigation="'+esc(i.id)+'"><span class="record-mark">⌖</span><span><b>'+esc(i.name)+'</b><small>'+esc(i.period||'Dates not set')+' · '+esc(i.site||SITE.name)+'</small></span><span class="record-id mono">'+esc(i.id)+'</span><span class="pill neutral">'+esc(i.status||'Draft')+'</span><span>↗</span></button>').join('')+'</div>';}
